   "data": "(function () {\n//ignore these variables, for the module stuff.\n    var module = {exports:null,filename:JSON.stringify(name)};\n    var require = function (a) {return gp_require(a,\"src/ggm2/ggm-gui/desktop/index.js\");};\n    var var__gvbvdxx_pack_filedata = null; //prevent overwrite\n    var cur_file = \"src/ggm2/ggm-gui/desktop/index.js\";\n    var ggm2path = require(\"src/paths.js\");\n    var isDesktop = require(\"src/\"+ggm2path+\"/ggm-gui/desktop/desktop-checker.js\");\n    if (isDesktop()) {\n        module.exports = require(\"src/\"+ggm2path+\"/ggm-gui/desktop/desktop-runtime.js\");\n        window.gui.isDesktopVersion = true;\n    } else {\n        window.gui.isDesktopVersion = false;\n        module.exports = null;\n    }\n    return module;\n})();",
